function validate([n, buildings]) {
  if (!Number.isInteger(n) || n < 2 || n > 100000) return 'n is between 2 and 10^5.';
  if (buildings.length < 1 || buildings.length > 100000) return 'buildings needs 1 to 10^5 entries.';
  const seen = new Set();
  for (const building of buildings) {
    if (!Array.isArray(building) || building.length !== 2) return 'Each building is a pair [x, y].';
    const [x, y] = building;
    if (!Number.isInteger(x) || !Number.isInteger(y) || x < 1 || y < 1 || x > n || y > n) return 'Each coordinate is between 1 and n.';
    const key = x * (n + 1) + y;
    if (seen.has(key)) return 'Two buildings cannot share coordinates.';
    seen.add(key);
  }
  return null;
}

