  const minY = new Map();
  const maxY = new Map();
  const minX = new Map();
  const maxX = new Map();
  for (const [x, y] of buildings) {
    minY.set(x, Math.min(minY.get(x) ?? y, y));
    maxY.set(x, Math.max(maxY.get(x) ?? y, y));
    minX.set(y, Math.min(minX.get(y) ?? x, x));
    maxX.set(y, Math.max(maxX.get(y) ?? x, x));
  }
  let covered = 0;
  for (const [x, y] of buildings) {
    const leftAndRight = minY.get(x) < y && y < maxY.get(x);
    const aboveAndBelow = minX.get(y) < x && x < maxX.get(y);
    if (leftAndRight && aboveAndBelow) {
      covered++;
    }
  }
  return covered;
}

