function countCoveredBuildings(n, buildings) {
  // Compare every building with every other one and note which directions are occupied.
  let count = 0;
  for (const [x, y] of buildings) {
    let left = false, right = false, above = false, below = false;
    for (const [a, b] of buildings) {
      if (a === x && b < y) left = true;
      if (a === x && b > y) right = true;
      if (b === y && a < x) above = true;
      if (b === y && a > x) below = true;
    }
    if (left && right && above && below) count++;
  }
  return count;
}

