function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? (rand() < 0.5 ? 100000 : int(50, 200)) : int(2, 6);
  // Buildings sit on a few chosen x lines and y lines, so many of them share rows and columns.
  const lines = size === 'large' ? Math.min(n, int(50, 120)) : n;
  const pickLines = () => {
    const chosen = new Set();
    while (chosen.size < lines) chosen.add(int(1, n));
    return [...chosen];
  };
  const xs = pickLines();
  const ys = pickLines();
  const cells = xs.length * ys.length;
  const count = size === 'large' ? Math.min(2000, cells) : int(1, cells);
  const picked = new Set();
  while (picked.size < count) picked.add(int(0, cells - 1));
  return [n, [...picked].map(cell => [xs[Math.floor(cell / ys.length)], ys[cell % ys.length]])];
}
